use std::path::{Path, PathBuf};
use tracing::{debug, info, warn};

/// Errors encountered when reading or writing sysfs CPU actuators.
#[derive(Debug)]
pub enum SysfsError {
    /// Target sysfs attribute was not found.
    NotFound(PathBuf),
    /// File I/O error reading or writing attribute.
    Io {
        path: PathBuf,
        source: io::Error,
    },
    /// Data parse error.
    Parse {
        path: PathBuf,
        content: String,
        message: String,
    },
}

impl std::fmt::Display for SysfsError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::NotFound(p) => write!(f, "Sysfs attribute not found: {}", p.display()),
            Self::Io { path, source } => {
                write!(f, "I/O error at '{}': {}", path.display(), source)
            }
            Self::Parse {
                path,
                content,
                message,
            } => write!(
                f,
                "Parse error at '{}' (content {:?}): {}",
                path.display(),
                content,
                message
            ),
        }
    }
}

impl std::error::Error for SysfsError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::Io { source, .. } => Some(source),
            _ => None,
        }
    }
}

