"//! UNIX Domain Stream Socket Server and Client for IPC
//!
//! Provides a non-blocking asynchronous socket server listening at
//! `/run/adaptive-protection-daemon/daemon.sock`.
//! Supports query-response and live event streaming.

use std::fs;
use std::io;
use std::path::{Path, PathBuf};
use std::sync::Arc;
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::net::{UnixListener, UnixStream};
use tokio::sync::{broadcast, RwLock};
use tracing::{debug, error, info, warn};

use super::protocol::{IpcCommand, IpcEvent, StatusResponse};

/// Errors encountered in IPC communication.
#[derive(Debug)]
pub enum IpcError {
    /// File I/O or socket error
    Io(io::Error),
    /// JSON serialization or deserialization failure
    Json(serde_json::Error),
    /// Daemon socket not found or not running
    SocketNotFound(PathBuf),
    /// Protocol syntax error
    Protocol(String),
}

impl std::fmt::Display for IpcError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Io(e) => write!(f, "IPC I/O error: {}", e),
            Self::Json(e) => write!(f, "IPC JSON error: {}", e),
            Self::SocketNotFound(p) => write!(
                f,
                "Adaptive protection daemon socket not found at '{}' (is the daemon running?)",
                p.display()
            ),
            Self::Protocol(msg) => write!(f, "IPC protocol error: {}", msg),
        }
    }
}

impl std::error::Error for IpcError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::Io(e) => Some(e),
            Self::Json(e) => Some(e),
            _ => None,
        }
    }
}

impl From<io::Error> for IpcError {
    fn from(e: io::Error) -> Self {
        Self::Io(e)
    }
}

impl From<serde_json::Error> for IpcError {
    fn from(e: serde_json::Error) -> Self {
        Self::Json(e)
    }
}

