"//! Desktop Notification Dispatcher and User Session Bus Discovery
//!
//! Because `adaptive-protection-daemon` runs as a system-level daemon, desktop
//! notification daemons (swaync, dunst, mako) are unreachable on the System Bus.
//!
//! This module implements:
//! 1. Active graphical user session discovery (locating `/run/user/<UID>/bus`).
//! 2. Direct session bus notification via `zbus` (invoking `org.freedesktop.Notifications`).
//! 3. Non-blocking asynchronous fork fallback via `/usr/bin/notify-send`.
//! 4. Notification deduplication ensuring only 1 notification is issued per `CRITICAL` event.

use std::fs;
use std::path::{Path, PathBuf};
use std::time::Instant;
use tracing::{debug, info, warn};

/// Discovers the active graphical user ID by scanning `/run/user/` for an active D-Bus session socket.
pub fn discover_active_user_session(run_user_dir: &Path) -> Option<u32> {
    if !run_user_dir.exists() {
        return None;
    }

    let mut candidate_uids = Vec::new();
    if let Ok(entries) = fs::read_dir(run_user_dir) {
        for entry in entries.flatten() {
            let name = entry.file_name();
            let name_str = name.to_string_lossy();
            if let Ok(uid) = name_str.parse::<u32>() {
                // Must be a non-system user (UID >= 1000)
                if uid >= 1000 {
                    let bus_path = entry.path().join("bus");
                    if bus_path.exists() {
                        candidate_uids.push(uid);
                    }
                }
            }
        }
    }

    candidate_uids.sort();
    candidate_uids.first().copied()
}

/// Notification manager providing rate-limited desktop notifications.
pub struct NotificationManager {
    run_user_dir: PathBuf,
    dry_run: bool,
    last_critical_notification: Option<Instant>,
    min_interval_secs: u64,
}

