//!
//! Provides:
//! - `apd-ctl rollback`: Out-of-process rollback hook used by systemd `ExecStopPost`:
//!   `ExecStopPost=/usr/local/bin/apd-ctl rollback`
//! - `apd-ctl status`: Queries live daemon state over UNIX domain stream socket (`daemon.sock`)
//!   or falls back to direct sysfs read.
//! - `apd-ctl monitor`: Streams live telemetry ticks and state transitions in real-time.

use clap::{Parser, Subcommand};
use std::path::PathBuf;
use tracing::{info, warn};

use adaptive_protection_daemon::actuator::cgroup::CgroupActuator;
use adaptive_protection_daemon::actuator::state_store::{execute_rollback, load_saved_state};
use adaptive_protection_daemon::actuator::sysfs::{BoostActuator, EppActuator};
