use adaptive_protection_daemon::ipc::socket::IpcClient;

#[derive(Parser, Debug)]
#[command(
    name = "apd-ctl",
    author = "Autonomous Systems Lab",
    version,
    about = "Control, telemetry monitoring, and fail-safe rollback CLI for adaptive-protection-daemon"
)]
struct Cli {
    /// Path to sysfs root directory (defaults to "/" or mock root)
    #[arg(long = "sysfs-root", default_value = "/")]
    sysfs_root: PathBuf,

    /// Explicit path to UNIX domain stream socket (defaults to /run/adaptive-protection-daemon/daemon.sock)
    #[arg(long = "socket-path")]
    socket_path: Option<PathBuf>,

    /// Dry run mode: print actions without writing to sysfs/cgroups
    #[arg(long = "dry-run", default_value_t = false)]
    dry_run: bool,

    #[command(subcommand)]
    command: Commands,
}

