"#[test]
fn test_apd_ctl_status_cli_fallback_to_sysfs() {
    let mock = MockSysfs::new().expect("Create mock sysfs");
    let mock_root = mock.root_path();

    let nonexistent_sock = mock_root.join("nonexistent.sock");

    let apd_ctl_bin = env!("CARGO_BIN_EXE_apd-ctl");
    let output = std::process::Command::new(apd_ctl_bin)
        .arg("--sysfs-root")
        .arg(mock_root)
        .arg("--socket-path")
        .arg(&nonexistent_sock)
        .arg("status")
        .output()
        .expect("Execute apd-ctl status fallback");

    assert!(output.status.success());
    let stdout = String::from_utf8_lossy(&output.stdout);
    assert!(
        stdout.contains("Daemon Socket: Unreachable"),
        "Stdout missing fallback banner: {}",
        stdout
    );
    assert!(
