"/// Whitelisted target descriptors. Targets matching these may be throttled or frozen.
pub const WHITELISTED_PATTERNS: &[&str] = &[
    "background.slice",
    "docker-",
    "podman-",
    "build.slice",
    "batch.slice",
];

/// Infrastructure blacklist: Protects compositor, session, authentication, audio, portals, and display services.
pub const INFRASTRUCTURE_BLACKLIST: &[&str] = &[
    "session.slice",
    "wayland-wm",
    "hyprland",
    "sddm",
    "seatd",
    "xdg-desktop-portal",
    "polkit",
    "swaync",
    "at-spi2",
    "pipewire",
    "wireplumber",
    "dbus",
    "init.scope",
    "systemd-journald",
    "systemd-logind",
    "systemd-resolved",
    "systemd-networkd",
    "systemd-timesyncd",
    "systemd-udevd",
];

/// Returns true only if the cgroup path is explicitly safe for resource containment.
/// Resolves Docker scopes inside system.slice while strictly safeguarding system infrastructure.
pub fn is_cgroup_safe_to_constrain(cgroup_rel_path: &str) -> bool {
    let lower = cgroup_rel_path.to_ascii_lowercase();

    // 1. Whitelist Check (Evaluated First for Container Scopes):
    // Permits docker-*.scope and podman-*.scope even when situated inside system.slice
    let is_whitelisted = WHITELISTED_PATTERNS.iter().any(|allowed| lower.contains(allowed));

    // 2. Strict Infrastructure Blacklist:
    for blocked in INFRASTRUCTURE_BLACKLIST {
        if lower.contains(blocked) {
            return false;
        }
    }

    // 3. System Slice Safety Gate:
