    /// Dispatches a critical memory warning notification to the active user session.
    pub async fn notify_memory_critical(&mut self, swap_percent: f64, psi_full: f64, now: Instant) {
        if let Some(last) = self.last_critical_notification {
            if now.duration_since(last).as_secs() < self.min_interval_secs {
                debug!("Critical notification suppressed by rate limiter");
                return;
            }
        }
        self.last_critical_notification = Some(now);

        let title = "CRITICAL: Memory & Swap Exhaustion Alert";
        let body = format!(
            "Swap is {:.1}% saturated (Memory Full Stall: {:.1}%).\nBackground tasks have been frozen to prevent desktop crash.",
