    assert_eq!(outcome.current_state, State::Normal);
    let mem = outcome.memory_pressure.expect("Memory pressure present");
    assert!((mem.some.avg10 - 25.0).abs() < 1e-4);
    assert!((mem.full.avg10 - 4.0).abs() < 1e-4);

    let swap = outcome.swap_telemetry.expect("Swap telemetry present");
    assert_eq!(swap.total_kib, 8 * 1024 * 1024);
    assert_eq!(swap.used_kib, 2 * 1024 * 1024);
    assert!((swap.used_percent - 25.0).abs() < 1e-2);
}
